def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def pos(obj, default=None):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        if default is None:
            return 0, 0
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_step_toward(src, tgt):
        return clamp_move(sgn(tgt[0] - src[0]), sgn(tgt[1] - src[1]))

    def safe_list(x):
        return x if isinstance(x, list) else []

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)), (0, 0))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return best_step_toward(self_pos, opp_pos)
        corners = [(0, 0)]
        if height:
            corners.append((0, height - 1))
        if width:
            corners.append((width - 1, 0))
        if width and height:
            corners.append((width - 1, height - 1))
        if not corners:
            return [0, 0]
        target = max(corners, key=lambda c: dist(c, opp_pos))
        return best_step_toward(self_pos, target)

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells")) or safe_list(observation.get("opponent_territory"))
        if not targets:
            targets = safe_list(observation.get("frontier")) or safe_list(observation.get("targets"))
