                valid.append((t[0], t[1]))
        if not valid:
            return [0, 0]
        # Prefer nearest unclaimed/frontier cell; break ties by moving toward opponent for pressure.
        best = min(valid, key=lambda c: (dist(c, self_pos), dist(c, opp_pos)))
        return best_step_toward(self_pos, best)

    resources = safe_list(observation.get("resources"))
    if resources:
        valid = []
        for r in resources:
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                valid.append((r[0], r[1]))
        if valid:
            best = min(valid, key=lambda c: dist(c, self_pos))
            return best_step_toward(self_pos, best)

    # Denial / fallback: move toward opponent if visible, else stay put.
    if ox != sx or oy != sy:
        return best_step_toward(self_pos, opp_pos)
